/**
 * Homepage "The AKSH Experience" section content (#experience, after Meet Our
 * Consultant). The former /experience route redirects there.
 *
 * Status: OWNER-SUPPLIED CONTENT, reproduced verbatim, including the "24/7
 * support" wording. Add no contact details, credentials or service promises
 * beyond this text.
 *
 * Illustrations are original AKSH artwork generated by
 * scripts/generate-experience-animations.mjs: a Lottie animation and a
 * matching static SVG (the settled illustration) for each step.
 */

export interface JourneyStep {
  number: string;
  title: string;
  description: string;
  illustration: {
    /** Lottie JSON: "reveal" marker once on entry, then "loop" repeated while in view. */
    animation: string;
    /** Static SVG: initial loading, reduced motion, failed loading, no JavaScript. */
    poster: string;
  };
}

export interface ExperienceContent {
  /** Section anchor (#experience); header "Our Experience" links here. */
  id: string;
  /** Owner-supplied "THE AKSH EXPERIENCE" masthead lettering; replaces a typed label. */
  artwork: {
    src: string;
    alt: string;
    width: number;
    height: number;
    /**
     * First and last pixel rows holding lettering (alpha >= 2); the rows
     * outside them are the file's own transparent margin, which the layout
     * offsets rather than crops.
     */
    ink: { top: number; bottom: number };
  };
  heading: string;
  /** Rendered italic. */
  tagline: string;
  steps: readonly JourneyStep[];
  /** Rendered bold. */
  closing: string;
  cta: { label: string; destinationName: string; href: string };
  status: "owner_supplied";
}

const illustration = (file: string) => ({
  animation: `/animations/experience/${file}.json`,
  poster: `/animations/experience/${file}.svg`,
});

